#include <stdio.h>
static int divide(int a,int b,int *out){if(b==0)return -1;*out=a/b;return 0;}
int main(void) {
    int a,b,result=0;if(scanf("%d%d",&a,&b)!=2)return 1;
    if(divide(a,b,&result)!=0)puts("ОШИБКА");else printf("%d\n",result);
    return 0;
}

