#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <ctype.h>
#include <math.h>
typedef struct { unsigned count, errors; double min, max, sum; } Stats;
static void consume(char *line, int too_long, Stats *stats) {
    if(too_long){++stats->errors;return;}
    char *end;errno=0;
    long timestamp=strtol(line,&end,10);
    if(end==line || errno==ERANGE || timestamp<0 || timestamp>1000000){++stats->errors;return;}
    while(isspace((unsigned char)*end))++end;
    if(*end!=','){++stats->errors;return;}
    char *start=end+1;errno=0;double value=strtod(start,&end);
    if(end==start || errno==ERANGE || !isfinite(value) || value < -1000 || value > 1000){++stats->errors;return;}
    while(isspace((unsigned char)*end))++end;
    if(*end){++stats->errors;return;}
    if(!stats->count || value<stats->min)stats->min=value;
    if(!stats->count || value>stats->max)stats->max=value;
    stats->sum+=value;++stats->count;
}
static int analyze(FILE *file, Stats *stats) {
    char line[128];size_t length=0;int overflow=0,ch;
    while((ch=fgetc(file))!=EOF){
        if(ch=='\n'){line[length]='\0';consume(line,overflow,stats);length=0;overflow=0;}
        else if(ch=='\0')overflow=1;
        else if(length<sizeof line-1)line[length++]=(char)ch;
        else overflow=1;
    }
    if(ferror(file))return 0;
    if(length || overflow){line[length]='\0';consume(line,overflow,stats);}
    return 1;
}
static double normalized(double value){return value==0.0 ? 0.0 : value;}
int main(void) {
    FILE *file=tmpfile();if(!file)return 1;
    int ch,ok=1;while((ch=fgetc(stdin))!=EOF)if(fputc(ch,file)==EOF){ok=0;break;}
    if(ferror(stdin))ok=0;
    Stats stats={0};
    if(ok && fseek(file,0,SEEK_SET)==0)ok=analyze(file,&stats);else ok=0;
    if(fclose(file)!=0)ok=0;
    if(!ok)return 1;
    if(!stats.count)printf("НЕТ ДАННЫХ %u\n",stats.errors);
    else printf("%u %.2f %.2f %.2f %u\n",stats.count,normalized(stats.min),normalized(stats.max),normalized(stats.sum/stats.count),stats.errors);
    return 0;
}
